-- Demande de Valentin : les modèles « Offensif » et « Défensif » de tous les joueurs reprennent les réglages optimisés,
-- même s'ils avaient été modifiés.
UPDATE manager_templates SET buildings = '[{"building":"ironmine","level":3},{"building":"claypit","level":3},{"building":"woodcutter","level":7},{"building":"claypit","level":8},{"building":"ironmine","level":10},{"building":"woodcutter","level":10},{"building":"warehouse","level":6},{"building":"farm","level":6},{"building":"claypit","level":13},{"building":"woodcutter","level":15},{"building":"ironmine","level":15},{"building":"claypit","level":16},{"building":"barracks","level":3},{"building":"farm","level":10},{"building":"warehouse","level":14},{"building":"woodcutter","level":19},{"building":"claypit","level":21},{"building":"ironmine","level":21},{"building":"farm","level":20},{"building":"woodcutter","level":25},{"building":"townhall","level":8},{"building":"claypit","level":28},{"building":"ironmine","level":27},{"building":"warehouse","level":19},{"building":"wall","level":18},{"building":"woodcutter","level":30},{"building":"warehouse","level":24},{"building":"ironmine","level":30},{"building":"claypit","level":30},{"building":"barracks","level":25},{"building":"market","level":20},{"building":"townhall","level":20},{"building":"warehouse","level":30}]'::jsonb,
